from s114_course_common import teach
S='pd-lensometry-p1'
teach(S,'lensometer-structure-1',[
(0,'把鏡片放上去，讀它對光做了什麼','焦度計量鏡片，不是在這台儀器上驗病人的眼睛。',[('Lensometer／focimeter','焦度計、驗度儀'),('S、C、axis','共同球面力量、兩主方向差、柱鏡軸'),('ADD／稜鏡','近區多的正力量／光被偏向哪裡多少')],'先辨眼鏡哪一面靠座、在哪個測點，讀數才有意義。'),
(2,'固定十字和可移動視標，是兩樣東西','你在對焦的是儀器視標，不是要讓自己的眼睛用力補。',[('目鏡','眼睛看入的一端，先調清固定刻度'),('分劃板reticle','固定十字與刻度，用來定位和讀稜鏡'),('可移動視標target','度數旋鈕移動它，直到圖案清楚')],'手動機型的望遠鏡與標像設計會影響所見方向；量稜鏡應按刻度標記，不靠鏡片移動方向猜。'),
(4,'先調目鏡，再確認空機零位','目鏡沒調好，可能把自己的調節誤差帶入讀值。',[('目鏡先放鬆調節','從較正／模糊側逐步到刻度剛清楚，按機型操作'),('沒放鏡片','視標清楚時應落在0D，必要時用標準鏡檢查'),('放待測鏡片','靠座、定位再轉度數鈕找清晰')],'零位和目鏡焦度不同；不是只把旋鈕指0就保證量測正確。')])
teach(S,'single-cylinder-1',[
(0,'長線短線一起清楚：兩方向力量相同','先調儀器，再用目標清晰度判鏡片。',[('球面鏡','各方向同力量，一次能把兩組線對清楚'),('球柱鏡','兩組線常在不同讀數清楚'),('軸旋鈕','讓散光標像對正方向，不是改鏡片本身的散光')],'同時清楚的判讀以儀器對準、狀態正常和此類視標為前提。'),
(2,'先取得兩個D，再算S和C','兩個數要記對各自的方向。',[('第一次清晰','記讀數與方向'),('第二次清晰','再記另一主方向，規則鏡片相差90°'),('轉負散','較正的當S，另一個減S當C')],'−1.25與−3.50 →S−1.25、C−2.25；軸不能只靠這兩個D猜。'),
(4,'短線長線，是這台視標的操作記法','最可靠的驗算仍是軸上S、垂直軸S+C。',[('較正讀值','含負數時，−1比−3更正'),('負散軸','沿不額外加柱鏡力量的方向'),('不同機型','線組、標記與讀軸方法可能不同，先確認實驗室規則')],'保留課堂短線／長線口訣，但不要把標像線方向直接等同所有儀器的同一主方向。')])
teach(S,'multifocal-prism-1',[
(0,'ADD：近區比遠區多了多少正力量','相減的兩個讀數，要用同一個頂點基準。',[('後頂點量遠用','後表面靠座，量遠區的常規度數'),('前頂點法量ADD','翻到前表面靠座，遠區和近區都用此前頂點法讀'),('ADD','近區前頂點−遠區前頂點')],'不能拿一個前頂點讀值減另一個後頂點；漸進鏡也要對準指定遠近參考點。'),
(2,'稜鏡像楔子：底厚、尖薄','光線偏向底；眼睛回推物體位置時，看起來朝尖端。',[('Base／apex','基底／頂端'),('BI／BO','每眼各自朝鼻／朝耳，左右眼的物理左右不同'),('BU／BD','朝上／朝下')],'先畫病人的左眼、右眼，再標基底，別用自己的觀看方向替代。'),
(4,'三個位置：瞳孔、光心、參考點','MRP是主要參考點，不是「最大正鏡至最佳視力」。',[('PD','pupillary distance，左右瞳孔中心距離'),('OC／DBOC','光學中心／兩片光心距離'),('MRP','major reference point，在指定點讀處方稜鏡')],'沒有處方稜鏡時常要光心對準視線；有設計稜鏡或漸進鏡，按指定參考點定位，不是所有情況都強求OC重合。')])
teach(S,'prentice-1',[
(0,'離光心越遠，同一鏡片越會偏光','Prentice算稜鏡大小，方向另判。',[('P＝c×|F|','P用Δ；c用cm；F用該方向D'),('8mm','先÷10成0.8cm'),('正3D、偏0.8cm','0.8×3＝2.4Δ；正鏡基底朝光心')],'負鏡基底背離光心；球柱鏡要用偏心方向的力量，不能一律取S。'),
(2,'兩眼在比相對偏移：先各畫一個箭頭','BI／BO是相對每眼命名，不是同一個空間左右。',[('右BO＋左BO','物理基底向相反左右，兩眼相對水平作用相加'),('右BU＋左BD','垂直反向，相對作用相加'),('兩眼都BU','共同上偏的部分抵消，剩下兩個量的差')],'求兩眼相對量和求兩眼共同看向哪裡，是不同問題。'),
(4,'1Δ：一米外偏一厘米','Δ不是角度°，也不是鏡片D。',[('稜鏡度Δ','偏移cm÷距離m'),('焦度計刻度','視標偏離中心的量；每圈幾Δ依機型'),('上偏2圈','課堂每圈1Δ時讀2ΔBU')],'稜鏡方向按儀器標法讀；換型號先核對刻度與像的方向。')])
